<?php

/**
 * Page of the missing PR previews (e.g. of a closed PR), sent by `.htaccess` the requests to `pr-<N>.<site>` when
 * `pr-<N>/` has no document root. Generated by the `ftp-archive-deploy` action: changes made here are overwritten.
 */

// URL of the repository of the PRs (empty: no links to them)
$repositoryUrl = '{{REPOSITORY_URL}}';

http_response_code(404);
header('Content-Type: text/html; charset=utf-8');
// The preview may be deployed in a moment
header('Cache-Control: no-store');
header('X-Robots-Tag: noindex');

$escape = fn (string $value): string => htmlspecialchars($value, ENT_QUOTES, 'UTF-8');

$host = strtolower($_SERVER['HTTP_HOST'] ?? '');
$pr = preg_match('/^pr-([0-9]+)\./', $host, $matches) ? $matches[1] : null;

?><!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex">
    <title><?= $pr !== null ? 'No preview for PR #'.$escape($pr) : 'Preview not found' ?></title>
    <style>
        :root { color-scheme: light dark; --muted: #57606a; --link: #0969da; }
        @media (prefers-color-scheme: dark) { :root { --muted: #9198a1; --link: #4493f8; } }
        body { margin: 0; padding: 3rem 1rem; font: 1rem/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
        main { max-width: 36rem; margin: 0 auto; }
        h1 { font-size: 1.5rem; margin: 0 0 1rem; }
        p, li { color: var(--muted); }
        a { color: var(--link); }
        .status { font-size: .875rem; font-weight: 600; letter-spacing: .05em; color: var(--muted); }
    </style>
</head>
<body>
<main>
    <p class="status">404</p>
<?php if ($pr !== null) { ?>
    <h1>No preview for PR #<?= $escape($pr) ?></h1>
    <p>Either:</p>
    <ul>
        <li>the PR was closed or merged, which removes its preview;</li>
        <li>its preview is not deployed yet: if the PR was just opened, try again in a few minutes;</li>
        <li>or there is no PR #<?= $escape($pr) ?>.</li>
    </ul>
<?php if ($repositoryUrl !== '') { ?>
    <p><a href="<?= $escape($repositoryUrl.'/pull/'.$pr) ?>">Open PR #<?= $escape($pr) ?> on GitHub</a></p>
<?php } ?>
<?php } else { ?>
    <h1>Preview not found</h1>
<?php } ?>
</main>
</body>
</html>
